from taf.internal.aliasing import aliasing_scope
from taf.hw.optical_attenuator.client.facade import OpticalAttenuatorClient


class client(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope("client", OpticalAttenuatorClient, name=__name__)

    def setup_attenuator(self,
                         server_ip,
                         vendor,
                         location,
                         server_port=8080,
                         model=None,
                         alias=None):
        """
        :param str server_ip: For example http://127.0.0.1 or 127.0.0.1
        :param str vendor: Name of a vendor, case insensitive.
        :param str location: Physical location where attenuator is connected.
            Available locations may be visible on server under
            http://server_ip:port/attenuators
        :param int server_port: Defaults to 8080
        :param str model: If None then default model is used.
        :param alias: name of returned client, if not given, default alias used

        :return: client object

        :raises: DeviceNotAvailable when no device is detected under given location
        """
        attenuator_client = OpticalAttenuatorClient()
        attenuator_client.setup_attenuator(server_ip, vendor, location, server_port, model)
        self.store.add(attenuator_client, alias)
        return attenuator_client

    @lookup_handler.implicit_lookup
    def get_current_attenuation(self, attenuator_port, client=None):
        """

        :param int attenuator_port: kingfisher - only 1 is supported
        :param client: alias of client, if not given default client used

        :return: float, for example 40.0
        """
        return client.get_current_attenuation(attenuator_port)

    @lookup_handler.implicit_lookup
    def set_attenuation(self, attenuator_port, attenuation_value, client=None):
        """

        :param int attenuator_port: kingfisher - only 1 is supported
        :param float attenuation_value: value of attenuation in db (not string '40db')
        :param client: alias of client, if not given default client used

        :return: None
        """
        attenuation_value = float(attenuation_value)
        return client.set_attenuation(attenuator_port, attenuation_value)
